/**
 * Derives the typed shape of an app/element's records from its catalog
 * `fields` bag — what `ctx.trigger.record` / `ctx.actions.<name>.record` expose
 * for record-bearing triggers and tasks (`recordCreated`, `recordSearch`,
 * `createRecord`, …).
 *
 * Most field types are scalar leaves (`TEXT` → `string`, `NUMBER` → `number`,
 * …). A few carry richer sub-properties that the platform resolves at
 * runtime, so their record value is an object instead — `DeepRef` then
 * exposes those sub-properties for drilling, e.g.
 * `ctx.trigger.record.severity.label`, `ctx.trigger.record.owner.email`,
 * or `ctx.trigger.record.parentTicket.recordId` (dynamic Dropdown).
 * Object shapes come from `entities/shared/types/platform.ts` so a
 * `User`/`Attachment`/… means the same thing everywhere in the SDK.
 *
 * Lives under the field entity (not engine): this is authoring-time field
 * value typing consumed by automations, not stream/build orchestration.
 */
import type { FieldRef } from "../../catalog/types.js";
import type { CalculationTypedValue } from "../shared/ref.js";
import type { Attachment, DropdownValue, DynamicDropdownValue, Group, RecordId, RichText, User } from "../shared/types/platform.js";
export type { RecordId } from "../shared/types/platform.js";
/** Map a platform field type literal to the TS type exposed on a record field. */
type CalculationTypeForField<FieldType extends string> = FieldType extends "NUMBER" ? "number" : FieldType extends "DECIMAL" ? "decimal" : FieldType extends "BOOLEAN" ? "bool" : FieldType extends "DATE" ? "date" : FieldType extends "DATETIME" ? "datetime" : FieldType extends "PICKLIST" | "PICKLIST_ID" ? "picklist" : FieldType extends "MULTI_PICKLIST" | "MULTI_PICKLIST_ID" ? "multiPicklist" : FieldType extends "ATTACHMENT" | "ATTACHMENT_ID" | "FILE" ? "attachment" : FieldType extends "USER" | "USER_ID" ? "user" : FieldType extends "GROUP" | "GROUP_ID" ? "group" : FieldType extends "JSON" | "OBJECT" ? "json" : FieldType extends "HTML" ? "html" : FieldType extends "HANDLE" ? "handle" : FieldType extends "RICH_TEXT" ? "text" : "text";
type RawFieldValueType<FieldType extends string> = FieldType extends "NUMBER" | "DECIMAL" ? number : FieldType extends "BOOLEAN" ? boolean : FieldType extends "JSON" | "OBJECT" ? unknown : FieldType extends "PICKLIST" | "PICKLIST_ID" ? DropdownValue : FieldType extends "MULTI_PICKLIST" | "MULTI_PICKLIST_ID" ? readonly DropdownValue[] : FieldType extends "ATTACHMENT" | "ATTACHMENT_ID" | "FILE" ? Attachment : FieldType extends "RICH_TEXT" ? RichText : FieldType extends "USER" | "USER_ID" ? User : FieldType extends "GROUP" | "GROUP_ID" ? Group : string;
type CalculatedFieldValueType<FieldType extends string> = CalculationTypedValue<RawFieldValueType<FieldType>, CalculationTypeForField<FieldType>>;
export type FieldValueType<Field extends string | FieldRef> = Field extends FieldRef<string, string, infer FieldType> ? FieldType extends "PICKLIST" | "PICKLIST_ID" ? Field extends {
    readonly dynamicSource: unknown;
} ? DynamicDropdownValue : DropdownValue : FieldType extends "MULTI_PICKLIST" | "MULTI_PICKLIST_ID" ? readonly (Field extends {
    readonly dynamicSource: unknown;
} ? DynamicDropdownValue : DropdownValue)[] : CalculatedFieldValueType<FieldType> : Field extends string ? CalculatedFieldValueType<Field> : never;
/**
 * Extract the `fields` bag off an app/element-like ref, e.g. `typeof catalog.myApp`.
 * `undefined` when the ref carries no `fields` bag (a hand-built `AppOrElementRef`
 * literal, or a ref kind — like a search table — that isn't field-typed yet).
 */
export type AppFieldsOf<A> = A extends {
    readonly fields: infer F extends Record<string, FieldRef>;
} ? F : undefined;
/**
 * The typed record shape for an app/element ref. When `A` carries a concrete
 * `fields` bag (a real catalog app), this is a closed, per-field-typed object —
 * an unknown field name is a compile error. Otherwise (no `fields` bag known)
 * extra names are not indexed: a `string` index would poison {@link RecordId}.
 *
 * Every record also carries its own HANDLE/ID under two different synthetic
 * keys, matching two independent (and both intentional) wire conventions —
 * neither has a bag key in `fields`:
 *   - `id` — for a trigger-sourced record (`ctx.trigger.record.id`), per
 *     `normalizeTriggerRefPath`'s `recordIdFieldClientHandle` → `"id"` case
 *     in `automations/materialize/ref-deserializer.ts`.
 *   - `recordId` — branded {@link RecordId} (ASPECT_RECORD_ID) for a
 *     task-output record (`ctx.actions.<t>.record.recordId`,
 *     `recordSearch`/`createRecord`/`findRelatedRecords`), per
 *     `rewriteForwardTaskRefName`'s `record.recordId` → wire `recordId`
 *     collapse in `automations/build.ts` (and its inverse in
 *     `ref-deserializer.ts`'s `buildTaskRef`).
 * `RecordShape` backs both trigger and task record accessors, so both keys
 * live here regardless of which context a given call site is in. The brand
 * on `recordId` is what lets `updateField.record` accept `.recordId` and
 * reject TEXT `.id` (edk#295).
 */
export type RecordShape<A> = {
    readonly id: string;
    readonly recordId: RecordId;
} & (AppFieldsOf<A> extends Record<string, FieldRef> ? {
    readonly [K in keyof AppFieldsOf<A>]: FieldValueType<AppFieldsOf<A>[K]>;
} : {});
